import numpy as np

class LogisticRegression:
    def __init__(self, X, y):
        self.X = X
        self.y = y

        self.w = np.random.randn(X.shape[1]+1)

    def sigmoid(self, z):
        return 1 / (1 + np.exp(-z))

    def fit(self, epochs):
        for _ in range(epochs):

            z = np.dot(self.X, self.w[1:]) + self.w[0]
            h = self.sigmoid(z)

            gradient = np.dot(self.X.T, (h - self.y))
            self.w[1:] += gradient

            bias = np.sum(h - self.y)
            self.w[0] += bias

    def predict(self, X):
        z = np.dot(X, self.w[1:]) + self.w[0]
        h = self.sigmoid(z)

        return h >= 0.5

