def main():
  board = create_board()
  winner = 0
  turn = PLAYER
  complete = False

  while not complete and not winner:
    if turn == PLAYER:
      player_move(board, PLAYER)
      turn = AI
    else:
      ai_move(board, AI)
      turn = PLAYER
    winner = check_winner(board)
